  /* Стоянка глубинников */
  v15_b_crownbit: { base: "v15_corer", n: "Живая коронка", g: "f",
    desc: "Колонковый автомат, сросшийся с обломком упавшей коронки: бурит под настилом, выныривает с разгона и бьёт зубьями по площади. Скрежет её слышен за ярус. ЭМИ берёт плохо, звук — хорошо.",
    mult: 6, beh: ["burrow", "charge", "splash"], snd: "sapper", sndRate: 0.6 },
